import styled from "styled-components";
import { Category, categoryState } from "../atoms";
import { useRecoilState } from "recoil";

const Tabs = styled.div`
	/* display: grid; */
	/* grid-template-columns: repeat(4, 1fr); */
	display: flex;
	margin:12px 0px;
	gap: 8px;
	/* border-bottom: 1px solid ${props => props.theme.bgColors.dimmed}; */
	/* border-bottom: 1px solid ${props => props.theme.bgColors.reversed}; */
`;

const Tab = styled.button<{isActive: boolean}>`
	text-align: center;
	font-size: 14px;
	font-weight: 400;
	padding: 6px 20px;
	border-radius: 12px; 
	background-color: ${(props) => props.theme.bgColors.dimmed};
	color: ${(props) => 
		props.isActive ? props.theme.brandColors.primary : props.theme.textColors.normal
	};
`;

function CategoryTabBar() {
	const [selectedCategory, setSelectedCategory] = useRecoilState(categoryState);
	const selectCategory = (cur: Category) => {
		setSelectedCategory((prev) => prev === cur ? null : cur)
	};
	const addNewCategory = () => {
		console.log("add new category")
		const newCategoryName = prompt("카테고리 이름을 입려해주세요.");
		console.log(newCategoryName)
	};

	return (
		<Tabs>
			<Tab 
				isActive={selectedCategory === Category.TO_DO} 
				onClick={ () => selectCategory(Category.TO_DO) }
			>to do</Tab>
			<Tab 
				isActive={selectedCategory === Category.IN_PROGRESS} 
				onClick={ () => selectCategory(Category.IN_PROGRESS) }
			>in progress</Tab>
			<Tab 
				isActive={selectedCategory === Category.DONE}
				onClick={ () => selectCategory(Category.DONE) }
			>done</Tab>
			<Tab isActive={false} onClick={addNewCategory}>
				+
			</Tab>
		</Tabs>
	);
}

export default CategoryTabBar;
